    ta: {"seat": "இருக்கை {1}", "connecting": "இணைக்கிறது...", "following": "பின்தொடர்கிறது", "followingOther": "பின்தொடர்கிறது (பக்கம் ஒன்றல்ல)", "opening": "திறக்கிறது...", "waitingTeacher": "ஆசிரியருக்காகக் காத்திருக்கிறது", "reconnecting": "மீண்டும் இணைக்கிறது...", "joining": "சேர்கிறது...", "notReachable": "வகுப்பை அடைய முடியவில்லை", "waitingClass": "வகுப்புக்காகக் காத்திருக்கிறது", "full": "வகுப்பு நிரம்பிவிட்டது", "busy": "பலர் ஒரே நேரத்தில் சேர்கின்றனர். சற்றுக் காத்திருக்கவும்...", "ended": "வகுப்பு முடிந்தது.", "exit": "வெளியேறு", "otherTab": "வேறு தாவலில் திறக்கவும்", "followHere": "இங்கே பின்தொடரவும்", "done": "முடிந்தது", "undoDone": "முடியவில்லை", "library": "நூலகம்", "back": "பின்செல்", "classCode": "வகுப்பு {1}", "ok": "சரி", "slow": "மெதுவாக", "bad": "தோல்வி", "endClass": "வகுப்பை முடிக்கவும்", "endConfirm": "எல்லா மாணவர்களுக்கும் வகுப்பை முடிக்கவா?", "cancel": "ரத்துசெய்", "seatsOk": "சரி: {1}", "seatsSlow": "மெதுவாக: {1}", "seatsBad": "தோல்வி: {1}", "seatsNotDone": "முடியவில்லை: {1}", "notFollowed": "மாணவர்கள் இந்தப் பக்கத்தைப் பார்ப்பதில்லை. அவர்கள் கடைசியாகப் பார்த்த பக்கத்திலேயே இருப்பார்கள்.", "appKiwix": "Wikipedia-ஐ ஆராய்", "appMaps": "வரைபடங்களில் வழிசெலுத்து", "appBooks": "ஒரு புத்தகம் படி", "linkOut": "இந்த இணைப்பு பெட்டிக்கு வெளியே செல்கிறது. வகுப்பில் இந்தப் பெட்டியின் பக்கங்களை மட்டுமே திறக்க முடியும்.", "notFound": "இந்தப் பக்கம் கிடைக்கவில்லை ({1}). மாணவர்கள் கடைசிப் பக்கத்திலேயே இருப்பார்கள்.", "noPageAnswer": "இந்தப் பக்கம் பதிலளிக்கவில்லை. மாணவர்கள் கடைசிப் பக்கத்திலேயே இருப்பார்கள்.", "boxNoAnswer": "பெட்டி பதிலளிக்கவில்லை. மீண்டும் முயற்சிக்கவும்.", "boxNotReachable": "பெட்டியை அடைய முடியவில்லை", "startAgain": "புதிய வகுப்பைத் தொடங்கவும்", "clearMarks": "அனைத்தையும் அழிக்கவும் ({1})", "markOutside": "உரையில் ஒரு சொல்லில் தொடங்கவும், அல்லது ஒரு படத்தைத் தட்டவும்.", "markLong": "குறைவான உரையைக் குறிக்கவும்: அதிகபட்சம் {1} பத்திகள்.", "marksFull": "ஒரு பக்கத்தில் {1} குறிகள் வரை இருக்கலாம். முதலில் ஒரு குறியை நீக்கவும்.", "markNotSent": "குறி வகுப்புக்குச் செல்லவில்லை. மீண்டும் முயற்சிக்கவும்.", "markBox": "செவ்வகம்", "markBoxHelp": "செவ்வகம் வரைய பக்கத்தில் இழுக்கவும். நகர்த்த, செவ்வகத்தை அழுத்திப் பிடிக்கவும். உருட்ட, கருவியை மீண்டும் தட்டவும்.", "markPen": "ஹைலைட்டர்", "markPenHelp": "முதல் சொல்லில் விரலை வைத்து, கடைசி சொல் வரை இழுக்கவும். உருட்ட, கருவியை மீண்டும் தட்டவும்.", "markArrow": "அம்பு", "markArrowHelp": "அம்பு வரைய வரைபடத்தில் இழுக்கவும். விரலை எடுக்கும் இடத்தை அம்பு காட்டும். நகர்த்த, அம்பை அழுத்திப் பிடிக்கவும். வரைபடத்தை நகர்த்த, கருவியை மீண்டும் தட்டவும்.", "markOval": "வட்டம்", "markOvalHelp": "வட்டம் வரைய பக்கத்தில் இழுக்கவும். நகர்த்த, வட்டத்தை அழுத்திப் பிடிக்கவும். உருட்ட, கருவியை மீண்டும் தட்டவும்.", "markEraser": "அழிப்பான்", "markEraserHelp": "ஒரு குறியை நீக்க அதைத் தட்டவும்.", "classAgain": "வகுப்பு புதிய குறியீட்டுடன் மீண்டும் தொடங்கியது. மாணவர்கள் மீண்டும் சேர வேண்டும்.", "doneOf": "{1}/{2}", "classCodeNamed": "வகுப்பு {1}: {2}"},
